select energy_manager.load_cards($cards$[
{"id":"p2-b05-041","paper":2,"topic":"Insulation payback","kind":"problem","front":"A 250 mm outer-diameter steam pipeline, 100 m long, is insulated with 150 mm mineral wool with a 70 °C surface. It is to be upgraded to 100 mm calcium silicate with a 55 °C surface. Ambient is 30 °C, boiler efficiency 87%, fuel GCV 10,200 kcal/kg, fuel oil Rs 45,000/t, 8,000 h/yr, upgrade cost Rs 20 lakh. Find the annual saving and simple payback.","back":"Annual saving about Rs 17.5 lakh per year; simple payback about 1.14 years (about 13.7 months).","explain":"Payback is the investment divided by the annual saving: 20 ÷ 17.5 ≈ 1.14 years.","flash":false,"source":"BEE Book 2 Ch 05 p193","steps":[{"prompt":"Find the heat loss per m² with mineral wool (70 °C surface).","answer":"S = [10 + (70 − 30)/20] × (70 − 30) = 12 × 40 = 480 kcal/h·m².","explain":"Same simplified formula, valid below 200 °C."},{"prompt":"Find the heat loss per m² with calcium silicate (55 °C surface).","answer":"S = [10 + (55 − 30)/20] × (55 − 30) = 11.25 × 25 = 281.25 kcal/h·m².","explain":"A lower surface temperature means a lower loss per unit area."},{"prompt":"Find the surface areas and total heat losses.","answer":"Mineral wool: area = 3.14 × 0.550 × 100 = 172.7 m², loss = 480 × 172.7 = 82,896 kcal/h. Calcium silicate: area = 3.14 × 0.450 × 100 = 141.3 m², loss = 281.25 × 141.3 ≈ 39,741 kcal/h.","explain":"Outer diameters are 250 + 2 × 150 = 550 mm and 250 + 2 × 100 = 450 mm."},{"prompt":"Find the annual saving in rupees.","answer":"(82,896 − 39,741) × 8,000 × 45,000 ÷ (10,200 × 1,000 × 0.87) ≈ Rs 17.5 lakh per year.","explain":"Fuel saved in kg is kcal saved ÷ (GCV × efficiency), then multiplied by the price per tonne."},{"prompt":"Find the simple payback period.","answer":"20 ÷ 17.5 ≈ 1.14 years ≈ 13.7 months.","explain":"Simple payback ignores interest and the time value of money."}],"order":2292},
{"id":"p2-b05-042","paper":2,"topic":"Heat loss calculation","kind":"problem","front":"A steam pipeline, 100 mm outer diameter and 100 m long, is uninsulated with a 180 °C surface. With 65 mm insulation the surface falls to 75 °C. Ambient is 30 °C, boiler efficiency 90%, fuel oil GCV 10,300 kcal/kg, and the plant runs 7,000 h/yr. Find the annual fuel oil saving in kg.","back":"About 32,190 kg per year (about 32 tonnes), or about Rs 4.2 lakh per year at Rs 13,000/t. The book gives no printed answer; this is derived from its formula.","explain":"Same method as the 170 °C case example: loss per m² from the formula, multiplied by area and hours, then converted to fuel. The 230 mm insulated diameter follows the book's own 65 mm example on a 100 mm pipe.","flash":false,"source":"BEE Book 2 Ch 05 p196","steps":[{"prompt":"Find S1 at 180 °C surface with ambient 30 °C.","answer":"S1 = [10 + (180 − 30)/20] × (180 − 30) = 17.5 × 150 = 2,625 kcal/h·m².","explain":"Within the 200 °C validity limit."},{"prompt":"Find S2 at 75 °C surface with ambient 30 °C.","answer":"S2 = [10 + (75 − 30)/20] × (75 − 30) = 12.25 × 45 = 551.25 kcal/h·m².","explain":"The insulated surface loss per m² is much lower."},{"prompt":"Find the surface areas before and after insulation.","answer":"A1 = 3.14 × 0.1 × 100 = 31.4 m²; A2 = 3.14 × 0.23 × 100 = 72.2 m².","explain":"Insulated outer diameter is 100 + 2 × 65 = 230 mm."},{"prompt":"Find total heat loss before and after, and the reduction.","answer":"Before: 2,625 × 31.4 ≈ 82,425 kcal/h; after: 551.25 × 72.2 ≈ 39,800 kcal/h; reduction ≈ 42,625 kcal/h.","explain":"The reduction in kcal/h drives the annual figure."},{"prompt":"Convert the reduction into an annual fuel oil saving.","answer":"Annual heat = 42,625 × 7,000 ≈ 298.4 million kcal/yr; fuel = 298,373,250 ÷ (10,300 × 0.9) ≈ 32,190 kg/yr.","explain":"Dividing by GCV × boiler efficiency gives the fuel that must be burnt to supply that heat."}],"order":2293},
{"id":"p2-b06-001","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What temperature range does fluidized bed combustion (FBC) operate in, and why does that avoid ash problems?","back":"About 840 °C to 950 °C. This is well below the ash fusion temperature, so melting of ash and associated problems are avoided.","explain":"Rapid mixing in the bed and heat extraction through in-bed tubes and bed walls keep the bed temperature low even though combustion is intense. Because the bed stays below ash fusion temperature, clinker and melting problems are avoided.","flash":false,"source":"BEE Book 2 Ch 06 p200","order":2294},
{"id":"p2-b06-002","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What is slip velocity in a fluidized bed, and why is a high value wanted?","back":"Slip velocity is the difference between mean solids velocity and mean gas velocity. Maximum slip is desirable for good heat transfer and intimate contact between solids and gas.","explain":"As gas velocity rises, mean solids velocity increases at a slower rate, so the gap widens (Figure 6.2). Good contact between gas and solids drives heat transfer in the bed.","flash":false,"source":"BEE Book 2 Ch 06 p200","order":2295},
{"id":"p2-b06-003","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Combustion needs three Ts. What are they, and how does FBC promote one of them?","back":"Time, Temperature and Turbulence. Fluidization promotes turbulence, which mixes the bed and spreads heat evenly at lower temperature.","explain":"FBC residence time is many times greater than in conventional grate firing, so heat is released efficiently at lower temperature. Improved mixing is what makes the lower combustion temperature work.","flash":true,"source":"BEE Book 2 Ch 06 p201","order":2296},
{"id":"p2-b06-004","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How does an FBC boiler control SO₂ and NOₓ without extra control equipment?","back":"Limestone used as the bed particle captures sulphur in the combustion chamber, and the low combustion temperature keeps NOₓ formation down.","explain":"Conventional boilers normally need separate flue gas treatment for these pollutants, so this is a major FBC advantage. The control takes place inside the combustion chamber itself.","flash":false,"source":"BEE Book 2 Ch 06 p201","order":2297},
{"id":"p2-b06-005","paper":2,"topic":"FBC Boilers","kind":"problem","front":"A coal has 2% sulphur. How much limestone is needed per tonne of coal in an FBC boiler, using the chapter's rule?","back":"60 kg of limestone per tonne of coal (6% of the coal feed).","explain":"The chapter gives 3% limestone for every 1% sulphur in the coal feed. The rule is applied as a percentage of coal, then converted to mass per tonne.","flash":false,"source":"BEE Book 2 Ch 06 p211","steps":[{"prompt":"Identify the chapter rule relating limestone to sulphur.","answer":"3% limestone is required for every 1% sulphur in the coal feed.","explain":"This is the pollution-control rule given for high-sulphur coal."},{"prompt":"Find the limestone percentage for 2% sulphur.","answer":"Limestone = 3 × 2 = 6% of coal feed.","explain":"The rule is linear, so the percentage scales with sulphur content."},{"prompt":"Convert to mass for 1 tonne (1,000 kg) of coal.","answer":"6% × 1,000 kg = 60 kg of limestone.","explain":"Sorbent feed is set by mass per tonne of coal fired."}],"order":2298},
{"id":"p2-b06-006","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What air velocity range is used through the bed in an AFBC, and what determines how much fuel can react?","back":"1.2 to 3.7 m/s. The rate at which air is blown through the bed determines the amount of fuel that can be reacted.","explain":"AFBC is a bubbling bed, and this velocity is lower than the 3.7 to 9 m/s used in circulating beds. Air flow therefore sets the fuel burning rate.","flash":false,"source":"BEE Book 2 Ch 06 p201","order":2299},
{"id":"p2-b06-007","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How much solid material is recycled from an AFBC bubbling bed per tonne of fuel burned?","back":"Only about 2 to 4 kg of solids per tonne of fuel.","explain":"Very little material leaves a bubbling bed. A CFBC recycles 50 to 100 kg per kg of fuel, which is a much larger flow.","flash":false,"source":"BEE Book 2 Ch 06 p202","order":2300},
{"id":"p2-b06-008","paper":2,"topic":"FBC Boilers","kind":"problem","front":"An AFBC burns 5 t/h of coal for 24 hours a day. How many kg of solids are recycled per day at 2 to 4 kg per tonne of fuel, and how does a CFBC compare at 50 to 100 kg per kg of fuel?","back":"240 to 480 kg/day in an AFBC; 6,000 to 12,000 t/day in a CFBC at the same fuel rate.","explain":"The gap between the two recycle flows explains why a CFBC needs large cyclones and a tall furnace, while a bubbling bed hardly recycles at all.","flash":false,"source":"BEE Book 2 Ch 06 p202","steps":[{"prompt":"Convert the fuel rate to tonnes per day.","answer":"5 t/h × 24 h = 120 t/day.","explain":"Recycle rates are given per tonne of fuel, so the daily fuel tonnage is needed first."},{"prompt":"Apply the AFBC recycle rate of 2 to 4 kg per tonne.","answer":"120 × 2 = 240 kg/day; 120 × 4 = 480 kg/day.","explain":"The AFBC bubbling bed recycles only a few kg per tonne of fuel."},{"prompt":"Apply the CFBC recycle rate of 50 to 100 kg per kg of fuel.","answer":"120,000 kg fuel/day × 50 = 6,000,000 kg (6,000 t); × 100 = 12,000 t/day.","explain":"The CFBC rate is per kg of fuel, so the fuel mass in kg is used here."},{"prompt":"How do the two recycle flows compare?","answer":"The CFBC recycle is about 12,500 to 50,000 times the AFBC recycle.","explain":"This huge solids flow is why CFBCs need large mechanical cyclones and a tall boiler."}],"order":2301},
{"id":"p2-b06-009","paper":2,"topic":"FBC Boilers","kind":"problem","front":"A bubbling bed is 1.2 m deep. Using the chapter's rule of about 1 inch of water per inch of bed depth, estimate its pressure drop. Compare with a 0.9 m bed.","back":"About 47 inches of water for the 1.2 m bed and about 35 inches for the 0.9 m bed. The shallow bed has the lower pressure drop and lower fan power.","explain":"The pressure drop rule links bed depth directly to fan power. A shallow bed keeps the drop, and so the fan load, lower.","flash":false,"source":"BEE Book 2 Ch 06 p202","steps":[{"prompt":"Convert 1.2 m to inches.","answer":"1.2 m ÷ 0.0254 m per inch = 47.2 in.","explain":"The rule is stated per inch of depth, so the depth must be in inches."},{"prompt":"Apply the rule of about 1 inch of water per inch of bed depth.","answer":"Pressure drop ≈ 47 inches of water.","explain":"The chapter says the drop averages about 1 inch of water per inch of depth."},{"prompt":"Repeat for the 0.9 m shallow bed.","answer":"0.9 m ÷ 0.0254 = 35.4 in, so ≈ 35 inches of water.","explain":"Same rule, shallower bed."},{"prompt":"Which bed needs less fan power, and why?","answer":"The 0.9 m shallow bed, because lower bed resistance gives lower pressure drop and fan power.","explain":"A deep bed raises pressure drop, which increases the effective gas velocity and fan power."}],"order":2302},
{"id":"p2-b06-010","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Within what temperature band must an AFBC bed be operated, and what goes wrong outside it?","back":"Roughly 800 °C to 950 °C. Above 950 °C there is risk of clinker in the bed; below 800 °C combustion efficiency is lost.","explain":"This narrow window is the main special feature of AFBC. Sulphur retention is best at 800 to 850 °C inside this band.","flash":false,"source":"BEE Book 2 Ch 06 p203","order":2303},
{"id":"p2-b06-011","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What bed temperature range gives efficient sulphur retention in an AFBC?","back":"800 °C to 850 °C.","explain":"This sub-range of the 800 to 950 °C window suits limestone sulphur capture. Going above 950 °C risks clinker.","flash":true,"source":"BEE Book 2 Ch 06 p203","order":2304},
{"id":"p2-b06-012","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How do over-bed and under-bed fuel feeding differ in fuel size and transport?","back":"Under-bed pneumatic feeding blows crushed coal (1 to 6 mm) through pipes that pierce the distributor. Over-bed feeding uses a screw conveyor and spreader for 6 to 10 mm coal, accepts oversize fuel and needs no transport lines.","explain":"Under-bed feeding needs more feed points as capacity rises, so fuel spreads evenly. Over-bed feeding is simpler because it removes the pneumatic transport lines.","flash":false,"source":"BEE Book 2 Ch 06 p203","order":2305},
{"id":"p2-b06-013","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What is the purpose of the air distributor in an FBC boiler, and how is it built?","back":"It introduces fluidizing air evenly across the bed cross-section, keeps particles moving and prevents de-fluidized zones. It is a perforated metal plate forming the furnace floor, with nozzles or bubble caps to stop solids falling back.","explain":"Uneven air distribution creates dead zones in the bed. The distributor plate itself must be protected by refractory, a static bed layer or water-cooled tubes.","flash":false,"source":"BEE Book 2 Ch 06 p204","order":2306},
{"id":"p2-b06-014","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Why does a shallow bed use less fan power than a deep bed?","back":"A shallow bed offers lower bed resistance and so a lower pressure drop. In a deep bed the pressure drop is higher, which raises the effective gas velocity and fan power.","explain":"Bed material is typically sand, ash, crushed refractory or limestone at about 1 mm average size. At the same fluidizing velocity, shallow and deep beds fluidize differently, which changes heat transfer to immersed surfaces.","flash":false,"source":"BEE Book 2 Ch 06 p204","order":2307},
{"id":"p2-b06-015","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What share of total ash in an FBC boiler is bottom ash, and how is it removed?","back":"About 30 to 40 percent of total ash is bottom ash; the rest is fly ash. Bed ash is removed by continuous overflow to hold bed height and by intermittent bottom drain for oversize particles.","explain":"Oversize particles must be drained to avoid accumulation and defluidization. Firing high-ash washery rejects greatly increases the overflow drain quantity.","flash":true,"source":"BEE Book 2 Ch 06 p205","order":2308},
{"id":"p2-b06-016","paper":2,"topic":"FBC Boilers","kind":"problem","front":"An FBC boiler produces 2,000 kg/h of total ash. How much is bottom ash and how much is fly ash if bottom ash is 30 to 40 percent?","back":"Bottom ash 600 to 800 kg/h; fly ash 1,200 to 1,400 kg/h.","explain":"Fly ash is the larger share in FBC, so the fly ash handling system is the heavier duty.","flash":false,"source":"BEE Book 2 Ch 06 p205","steps":[{"prompt":"Find the bottom ash at 30%.","answer":"0.30 × 2,000 = 600 kg/h.","explain":"Bottom ash is stated as a share of total ash."},{"prompt":"Find the bottom ash at 40%.","answer":"0.40 × 2,000 = 800 kg/h.","explain":"The upper end of the chapter's range."},{"prompt":"Find the fly ash as the balance.","answer":"2,000 − 600 = 1,400 kg/h; 2,000 − 800 = 1,200 kg/h.","explain":"Fly ash is whatever ash is not bottom ash."},{"prompt":"Why does the fly ash share matter for plant design?","answer":"Fly ash is much higher than in conventional boilers because particles are elutriated at high velocity.","explain":"The chapter notes this makes the dust collection stages (cyclones, bag filters, ESPs) a major part of the design."}],"order":2309},
{"id":"p2-b06-017","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How does an electrostatic precipitator (ESP) collect fly ash?","back":"A high voltage on discharge wires creates an electric field and ionizes the gas. Charged dust particles are pulled by Coulomb force onto collecting plates, which are cleaned by rapping, water washing or hopper removal.","explain":"Ions from the discharge wires charge the dust, and the electric field drives it to the plates. ESPs are one of the dust collectors used in FBC systems, alongside cyclones and bag filters.","flash":false,"source":"BEE Book 2 Ch 06 p205","order":2310},
{"id":"p2-b06-018","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What fraction of fly ash can an ESP remove from flue gas?","back":"95 to 99 percent.","explain":"The remaining 1 to 5 percent leaves with the flue gas, so the efficiency directly sets the stack dust load.","flash":true,"source":"BEE Book 2 Ch 06 p205","order":2311},
{"id":"p2-b06-019","paper":2,"topic":"FBC Boilers","kind":"problem","front":"An ESP receives 500 kg/h of fly ash in flue gas. How much is collected and how much leaves the stack at 95% efficiency and at 99% efficiency?","back":"At 95%: 475 kg/h collected, 25 kg/h emitted. At 99%: 495 kg/h collected, 5 kg/h emitted.","explain":"Moving from 95% to 99% cuts the stack dust load fivefold in this example.","flash":false,"source":"BEE Book 2 Ch 06 p205","steps":[{"prompt":"Find the collected fly ash at 95%.","answer":"0.95 × 500 = 475 kg/h.","explain":"ESP efficiency is the fraction of fly ash removed."},{"prompt":"Find the fly ash emitted at 95%.","answer":"500 − 475 = 25 kg/h.","explain":"Whatever is not collected leaves in the flue gas."},{"prompt":"Find the collected fly ash at 99%.","answer":"0.99 × 500 = 495 kg/h.","explain":"Upper end of the chapter's range."},{"prompt":"Find the fly ash emitted at 99%, and the change in stack load.","answer":"500 − 495 = 5 kg/h; 25 kg/h ÷ 5 kg/h = 5 times lower.","explain":"Small efficiency gains give large cuts in stack dust at high removal levels."}],"order":2312},
{"id":"p2-b06-020","paper":2,"topic":"FBC Boilers","kind":"fact","front":"In a CFBC, what share of total combustion air is upward fluidizing air, and where does the rest enter?","back":"60 to 70 percent of total air is upward fluidizing air through the bottom distribution nozzles. The balance enters above the bottom of the furnace as secondary air.","explain":"Fuel and limestone are suspended in the fluidizing air stream, which runs at 3.7 to 9 m/s. The secondary air completes combustion above the bed.","flash":false,"source":"BEE Book 2 Ch 06 p206","order":2313},
{"id":"p2-b06-021","paper":2,"topic":"FBC Boilers","kind":"problem","front":"A CFBC supplies 10,000 m³/h of total combustion air. How much enters as fluidizing (bottom) air and how much as secondary air?","back":"Fluidizing air 6,000 to 7,000 m³/h; secondary air 3,000 to 4,000 m³/h.","explain":"The 60 to 70 percent split fixes the bottom air. Everything else must be secondary air.","flash":false,"source":"BEE Book 2 Ch 06 p206","steps":[{"prompt":"Find the bottom air at 60%.","answer":"0.60 × 10,000 = 6,000 m³/h.","explain":"Lower end of the chapter's range for upward fluidizing air."},{"prompt":"Find the bottom air at 70%.","answer":"0.70 × 10,000 = 7,000 m³/h.","explain":"Upper end of the range."},{"prompt":"Find the secondary air as the balance.","answer":"10,000 − 7,000 = 3,000 m³/h; 10,000 − 6,000 = 4,000 m³/h.","explain":"The secondary air is what is left after the bottom air."},{"prompt":"Check the totals.","answer":"Each pair adds to 10,000 m³/h.","explain":"Confirms the split is consistent with total air."}],"order":2314},
{"id":"p2-b06-022","paper":2,"topic":"FBC Boilers","kind":"fact","front":"At what temperature does CFBC combustion take place, and what happens to fine particles?","back":"840 to 900 °C. Fine particles below 450 microns are elutriated out of the furnace by flue gas at 4 to 6 m/s, then collected by solids separators and recycled.","explain":"Solids circulation keeps the temperature fairly uniform. The chapter says the controlling parameters are temperature, residence time and turbulence, as in pulverized coal firing.","flash":false,"source":"BEE Book 2 Ch 06 p206","order":2315},
{"id":"p2-b06-023","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How much solid is recycled in a CFBC per kg of fuel burnt?","back":"50 to 100 kg of solids per kg of fuel.","explain":"The large recycle carries bed material back to the furnace, giving longer residence time for carbon and limestone use and efficient heat transfer to the furnace walls.","flash":false,"source":"BEE Book 2 Ch 06 p206","order":2316},
{"id":"p2-b06-024","paper":2,"topic":"FBC Boilers","kind":"problem","front":"A CFBC burns 12 t/h of coal. How much solids circulate per hour at 50 to 100 kg per kg of fuel?","back":"600 to 1,200 t/h of solids.","explain":"Compared with 2 to 4 kg per tonne in an AFBC, the CFBC circulating load is enormous, which is why its separators must be large.","flash":false,"source":"BEE Book 2 Ch 06 p206","steps":[{"prompt":"Convert the fuel rate to kg/h.","answer":"12 t/h = 12,000 kg/h.","explain":"The recycle rate is per kg of fuel, so the fuel rate must be in kg."},{"prompt":"Apply the lower rate of 50 kg per kg of fuel.","answer":"12,000 × 50 = 600,000 kg/h = 600 t/h.","explain":"Lower end of the CFBC range."},{"prompt":"Apply the upper rate of 100 kg per kg of fuel.","answer":"12,000 × 100 = 1,200,000 kg/h = 1,200 t/h.","explain":"Upper end of the range."},{"prompt":"What does this flow require of the separators?","answer":"Large mechanical cyclones capable of capturing and recycling the solids, which is why a CFBC needs a tall boiler.","explain":"The chapter ties the huge recycle to the cyclone size and boiler height."}],"order":2317},
{"id":"p2-b06-025","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Name three conditions under which a CFBC is a good choice over other FBC types.","back":"Boiler capacity is large to medium; sulphur emission and NOₓ control are important; and the boiler must fire low-grade fuel or fuel of highly fluctuating quality.","explain":"CFBC is generally more economical than AFBC for industrial steam above about 75 to 100 t/h, but needs huge cyclones and a tall boiler.","flash":false,"source":"BEE Book 2 Ch 06 p207","order":2318},
{"id":"p2-b06-026","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What is the principle of a circulating fluidized bed combustion (CFBC) boiler?","back":"Crushed fuel and limestone are suspended in upward air (60 to 70 percent of total air). Fine particles are carried out, separated by cyclones and recycled into the furnace. Combustion is controlled by temperature, residence time and turbulence.","explain":"Solids circulation moves heat transfer outside the combustion zone (convection section, water walls and riser exit) and gives longer residence time for carbon and limestone use.","flash":false,"source":"BEE Book 2 Ch 06 p206","order":2319},
{"id":"p2-b06-027","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Explain the difference between CFBC and AFBC.","back":"CFBC runs at 3.7 to 9 m/s with 6 to 12 mm fuel and recycles 50 to 100 kg per kg of fuel. AFBC runs at 1.2 to 3.7 m/s with 1 to 10 mm coal and recycles 2 to 4 kg per tonne. CFBC uses calcium more efficiently (1.5:1 against 3.2:1 for AFBC).","explain":"AFBC keeps its heat transfer tubes immersed in the bed, while the CFBC has none and moves heat transfer to the convection section and walls. CFBC suits large capacity and low-grade or fluctuating fuel.","flash":false,"source":"BEE Book 2 Ch 06 p206","order":2320},
{"id":"p2-b06-028","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How does a pressurized fluidized bed combustion (PFBC) system generate power, and what efficiency gain does it give?","back":"The bed vessel operates up to 16 ata. Off-gas drives a gas turbine, steam for a steam turbine is raised in tubes immersed in the bed, and turbine exhaust preheats the condensate. Overall conversion efficiency is 5 to 8 percent higher.","explain":"Combining gas and steam turbines is why PFBC generates electricity more efficiently than a conventional system, and it suits cogeneration or combined cycle power. Elevated pressure also reduces boiler size considerably.","flash":true,"source":"BEE Book 2 Ch 06 p208","order":2321},
{"id":"p2-b06-029","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What aspects must be considered in a retrofit project converting a conventional boiler to FBC?","back":"Water/steam circulation design; furnace bottom-grate clearance; type of particulate control device; fan capacity; and availability of space.","explain":"Retrofits have been carried out successfully in India and abroad. Conversion can be done without major changes after a cost-benefit analysis, and oil-fired boilers can also be converted case by case.","flash":false,"source":"BEE Book 2 Ch 06 p210","order":2322},
{"id":"p2-b06-030","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What changes does retrofitting a stoker-fired water tube boiler to FBC involve?","back":"Replace the grate with a distributor plate having short stand pipes for air from the wind box; add stand pipes to remove bed ash; add horizontal hairpin tubes in the bed with a forced-circulation pump from the drum; and modify the crusher to size the coal/limestone mix for under-bed injection.","explain":"The forced-circulation pump moves water from the boiler drum through the hairpin tubes in the bed. The crusher change lets the coal and limestone mix be injected pneumatically under the bed.","flash":false,"source":"BEE Book 2 Ch 06 p210","order":2323},
{"id":"p2-b06-031","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What combustion efficiency and overall efficiency do FBC boilers achieve?","back":"Combustion efficiency over 95 percent irrespective of ash content; overall efficiency around 84 percent, plus or minus 2 percent.","explain":"Efficiency holds even with high-ash fuels. The chapter also notes that high heat transfer over a small immersed area reduces overall boiler size.","flash":true,"source":"BEE Book 2 Ch 06 p210","order":2324},
{"id":"p2-b06-032","paper":2,"topic":"FBC Boilers","kind":"problem","front":"An FBC boiler receives 10 MW of fuel heat. Using the chapter's overall efficiency of 84% plus or minus 2%, what steam heat output should be expected?","back":"8.2 MW to 8.6 MW, with 8.4 MW at the mid-point.","explain":"Overall efficiency is useful output divided by fuel heat input, so the balance of 1.6 MW at the mid-point is the total loss.","flash":false,"source":"BEE Book 2 Ch 06 p210","steps":[{"prompt":"Find the output at the lower limit, 82%.","answer":"10 × 0.82 = 8.2 MW.","explain":"84 minus 2 percent."},{"prompt":"Find the output at the upper limit, 86%.","answer":"10 × 0.86 = 8.6 MW.","explain":"84 plus 2 percent."},{"prompt":"Find the output at the mid-point, 84%.","answer":"10 × 0.84 = 8.4 MW.","explain":"The chapter's stated overall efficiency."},{"prompt":"How much of the fuel heat is not delivered as output at the mid-point?","answer":"10 − 8.4 = 1.6 MW.","explain":"This is the total loss the efficiency figure accounts for."}],"order":2325},
{"id":"p2-b06-033","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What is the highest ash content and lowest calorific value of coal that an FBC boiler can fire at rated output?","back":"Ash content up to 62 percent and calorific value as low as 2,500 kcal/kg. Carbon of only 1 percent by weight can sustain fluidized bed combustion.","explain":"This is why FBC is suited to low-grade fuels that conventional firing cannot handle well. Fines below 6 mm can also be burnt efficiently.","flash":false,"source":"BEE Book 2 Ch 06 p211","order":2326},
{"id":"p2-b06-034","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What excess air does FBC operate at, and what does high CO₂ in the flue gas indicate?","back":"Only 20 to 25 percent excess air, because CO₂ in flue gas is about 14 to 15 percent at full load.","explain":"High CO₂ at low excess air shows that combustion is efficient. Operating at low excess air fits the high combustion efficiency FBC achieves.","flash":false,"source":"BEE Book 2 Ch 06 p211","order":2327},
{"id":"p2-b06-035","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What fuel saving can a pressurized FBC combined with a gas turbine and steam turbine offer?","back":"A potential fuel saving of at least 4 percent.","explain":"Operating the bed at elevated pressure produces hot pressurized gases that power a gas turbine, combined with a conventional steam turbine to improve electricity efficiency.","flash":false,"source":"BEE Book 2 Ch 06 p212","order":2328},
{"id":"p2-b06-036","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What problem does high silica in biomass such as rice husk cause in an FBC boiler?","back":"Frequent erosion of super-heater and economizer coils.","explain":"The chapter lists this among biomass-firing issues, alongside tube fouling from sand and mud in the fuel.","flash":false,"source":"BEE Book 2 Ch 06 p213","order":2329},
{"id":"p2-b06-037","paper":2,"topic":"FBC Boilers","kind":"fact","front":"How much chloride can cotton stalk contain, and what does it do in the boiler?","back":"About 8 to 9 percent. Chloride combines with sodium and potassium at high temperature and aggravates corrosion of boiler internals, especially super-heater tubes.","explain":"Red gram husk and twigs cause a different problem: cold-end corrosion of secondary super-heater and economizer tubes, because of their sulphur content.","flash":false,"source":"BEE Book 2 Ch 06 p213","order":2330},
{"id":"p2-b06-038","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Why is it hard to set a workable air-to-fuel ratio in a biomass FBC boiler?","back":"Fuel mixes often contain 6 to 7 biomass types, each with its own air-to-fuel ratio.","explain":"Size variation and high moisture also cause unburnts and steam pressure fluctuations, so one ratio for the whole mix is difficult to set.","flash":false,"source":"BEE Book 2 Ch 06 p213","order":2331}
]$cards$::jsonb);
